import assert from 'node:assert/strict';
import test, {type TestContext} from 'node:test';
import {mkdtemp, mkdir, writeFile, rm, rmdir, symlink, readFile} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import path from 'node:path';
import {crc32, deflateRawSync} from 'node:zlib';
import {assertNarutoOutputParent, validateNarutoWebDistribution} from '../../scripts/prepare-naruto-web.mjs';
import {validateNarutoExtensionArchive} from '../../scripts/lib/naruto-extension-archive.mjs';

const extensionManifest = {
  manifest_version: 3, name: 'Synthetic Naruto collector', version: '0.1.0',
  permissions: ['tabs', 'scripting', 'storage'],
  host_permissions: ['https://www.bilibili.com/*', 'https://search.bilibili.com/*',
    'https://t.bilibili.com/*', 'https://api.bilibili.com/*'],
  background: {service_worker: 'background.js', type: 'module'},
  content_scripts: [{matches: ['https://kashewt.com/naruto*', 'http://127.0.0.1/naruto*', 'http://localhost/naruto*'],
    js: ['portal.js'], run_at: 'document_start', all_frames: false}],
  content_security_policy: {extension_pages: "script-src 'self'; object-src 'none'"}
};
const extensionFiles = () => ({'manifest.json': JSON.stringify(extensionManifest),
  'background.js': 'globalThis.syntheticCollector = true;', 'portal.js': 'globalThis.syntheticPortal = true;'});

/** Writes independent standard ZIP fixtures, including streaming descriptors used by the build tool. */
const extensionZip = (files: Record<string, string | Buffer> = extensionFiles(), compressed = false, descriptor = false,
  trailingCompressed = false) => {
  const localEntries: Buffer[] = [], centralEntries: Buffer[] = [];
  let offset = 0;
  for (const [filename, value] of Object.entries(files)) {
    const name = Buffer.from(filename), source = Buffer.from(value), payload = compressed
      ? Buffer.concat([deflateRawSync(source), trailingCompressed ? Buffer.from('unparsed') : Buffer.alloc(0)]) : source;
    const crc = crc32(source), flags = 0x0800 | (descriptor ? 8 : 0), method = compressed ? 8 : 0;
    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50); local.writeUInt16LE(20, 4); local.writeUInt16LE(flags, 6); local.writeUInt16LE(method, 8);
    if (!descriptor) {local.writeUInt32LE(crc, 14); local.writeUInt32LE(payload.length, 18); local.writeUInt32LE(source.length, 22);}
    local.writeUInt16LE(name.length, 26);
    const trailer = Buffer.alloc(descriptor ? 16 : 0);
    if (descriptor) {
      trailer.writeUInt32LE(0x08074b50); trailer.writeUInt32LE(crc, 4);
      trailer.writeUInt32LE(payload.length, 8); trailer.writeUInt32LE(source.length, 12);
    }
    const central = Buffer.alloc(46);
    central.writeUInt32LE(0x02014b50); central.writeUInt16LE(20, 4); central.writeUInt16LE(20, 6);
    central.writeUInt16LE(flags, 8); central.writeUInt16LE(method, 10); central.writeUInt32LE(crc, 16);
    central.writeUInt32LE(payload.length, 20); central.writeUInt32LE(source.length, 24);
    central.writeUInt16LE(name.length, 28); central.writeUInt32LE(offset, 42);
    const entry = Buffer.concat([local, name, payload, trailer]);
    localEntries.push(entry); centralEntries.push(Buffer.concat([central, name])); offset += entry.length;
  }
  const central = Buffer.concat(centralEntries), end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50); end.writeUInt16LE(centralEntries.length, 8); end.writeUInt16LE(centralEntries.length, 10);
  end.writeUInt32LE(central.length, 12); end.writeUInt32LE(offset, 16);
  return Buffer.concat([...localEntries, central, end]);
};

/** Isolates generated distributions from both production bundles and private local configuration. */
const fixture = async (context: TestContext) => {
  const root = await mkdtemp(path.join(tmpdir(), 'archtree-naruto-fixture-'));
  context.after(async () => {
    assert.equal(path.dirname(path.resolve(root)), path.resolve(tmpdir()));
    assert.ok(path.basename(root).startsWith('archtree-naruto-fixture-'));
    await rm(root, {recursive: true, force: true});
  });
  await mkdir(path.join(root, 'assets'));
  await mkdir(path.join(root, '.vite'));
  await writeFile(path.join(root, 'index.html'), '<script src="/naruto/assets/index-abcdefgh.js"></script>');
  await writeFile(path.join(root, 'assets', 'index-abcdefgh.js'), 'export {};');
  await writeFile(path.join(root, '.vite', 'manifest.json'), JSON.stringify({'index.html': {file: 'assets/index-abcdefgh.js', isEntry: true}}));
  await writeFile(path.join(root, 'naruto-mobile-chrome-extension.zip'), extensionZip());
  return root;
};

test('Naruto distribution requires independent /naruto assets and an extension package', async context => {
  const root = await fixture(context);
  const result = await validateNarutoWebDistribution(root);
  assert.match(result.distributionSha256, /^[0-9a-f]{64}$/);
  await writeFile(path.join(root, 'index.html'), '<script src="/assets/index-abcdefgh.js"></script>');
  await assert.rejects(validateNarutoWebDistribution(root), /base path/);
});

test('Naruto preparation refuses a junction parent before replacing an external distribution', async context => {
  const root = await fixture(context), parent = path.join(root, 'naruto-web');
  await mkdir(parent);
  await assertNarutoOutputParent(parent, root);
  await rmdir(parent);
  const outside = path.join(root, 'outside');
  await mkdir(outside);
  await writeFile(path.join(outside, 'keep.txt'), 'fixture target must remain unchanged');
  await symlink(outside, parent, process.platform === 'win32' ? 'junction' : 'dir');
  await assert.rejects(assertNarutoOutputParent(parent, root), /escapes/);
  assert.equal(await readFile(path.join(outside, 'keep.txt'), 'utf8'), 'fixture target must remain unchanged');
});

test('Naruto distribution excludes private configuration, unexpected files and unmanifested assets', async context => {
  const root = await fixture(context);
  await writeFile(path.join(root, 'assets', 'unreferenced-abcdefgh.js'), 'export {};');
  await assert.rejects(validateNarutoWebDistribution(root), /Unmanifested/);
  await rm(path.join(root, 'assets', 'unreferenced-abcdefgh.js'));
  await writeFile(path.join(root, '.env'), 'SYNTHETIC_FIXTURE=never-shipped');
  await assert.rejects(validateNarutoWebDistribution(root), /Unexpected/);
});

test('Naruto release provenance detects a modified distribution before artifact staging', async context => {
  const root = await fixture(context);
  const {distributionSha256, extensionVersion} = await validateNarutoWebDistribution(root);
  assert.equal(extensionVersion, '0.1.0');
  const provenance = {schemaVersion: 1, protocolVersion: 1, basePath: '/naruto/', sourceCommit: 'a'.repeat(40), sourceDirty: true, distributionSha256, extensionVersion};
  await writeFile(path.join(root, '.archtree-naruto-build'), 'v1\n');
  await writeFile(path.join(root, 'release-source.json'), JSON.stringify({...provenance, extensionVersion: '0.0.9'}));
  await assert.rejects(validateNarutoWebDistribution(root, true), /provenance/);
  await writeFile(path.join(root, 'release-source.json'), JSON.stringify(provenance));
  await validateNarutoWebDistribution(root, true);
  await writeFile(path.join(root, 'assets', 'index-abcdefgh.js'), 'export const changed = true;');
  await assert.rejects(validateNarutoWebDistribution(root, true), /provenance/);
});

test('Naruto extension packages fully decode stored and deflated files with streaming descriptors', () => {
  for (const compressed of [false, true]) for (const descriptor of [false, true]) {
    assert.doesNotThrow(() => validateNarutoExtensionArchive(extensionZip(extensionFiles(), compressed, descriptor)));
  }
});

test('Naruto extension packages allow dedicated tab groups without other permission expansion', () => {
  const grouped = {...extensionManifest, version: '0.1.3', permissions: [...extensionManifest.permissions, 'tabGroups']};
  const files = {...extensionFiles(), 'manifest.json': JSON.stringify(grouped)};
  assert.doesNotThrow(() => validateNarutoExtensionArchive(extensionZip(files, true, true)));
  for (const permissions of [[...grouped.permissions, 'cookies'], [...grouped.permissions, 'debugger'],
    [...grouped.permissions, 'tabGroups'], ['tabs', 'tabGroups', 'scripting']]) {
    assert.throws(() => validateNarutoExtensionArchive(extensionZip({...files,
      'manifest.json': JSON.stringify({...grouped, permissions})})), /permissions/);
  }
  assert.throws(() => validateNarutoExtensionArchive(extensionZip({...files,
    'manifest.json': JSON.stringify({...grouped, host_permissions: [...grouped.host_permissions, '<all_urls>']})})), /permissions/);
});

test('Naruto distribution rejects corrupt CRCs, extra packaged files, and truncated extension downloads', async context => {
  const root = await fixture(context), zipPath = path.join(root, 'naruto-mobile-chrome-extension.zip');
  const corrupt = extensionZip();
  corrupt[30 + Buffer.byteLength('manifest.json') + 5] ^= 1;
  await writeFile(zipPath, corrupt);
  await assert.rejects(validateNarutoWebDistribution(root), /CRC/);
  await writeFile(zipPath, extensionZip({...extensionFiles(), '.env': 'SYNTHETIC=excluded'}));
  await assert.rejects(validateNarutoWebDistribution(root), /unexpected files/);
  await writeFile(zipPath, extensionZip().subarray(0, -8));
  await assert.rejects(validateNarutoWebDistribution(root), /incomplete/);
});

test('Naruto extension validation refuses expanded bombs, permission drift and inconsistent local headers', () => {
  const oversized = extensionZip(extensionFiles(), true);
  const centralOffset = oversized.readUInt32LE(oversized.length - 6);
  oversized.writeUInt32LE(8 * 1024 * 1024 + 1, centralOffset + 24);
  assert.throws(() => validateNarutoExtensionArchive(oversized), /oversized/);
  assert.throws(() => validateNarutoExtensionArchive(extensionZip({...extensionFiles(),
    'manifest.json': JSON.stringify({...extensionManifest, permissions: [...extensionManifest.permissions, 'cookies']})})), /permissions/);
  const localMismatch = extensionZip();
  localMismatch.writeUInt32LE(0, 22);
  assert.throws(() => validateNarutoExtensionArchive(localMismatch), /local size/);
  const trailing = Buffer.concat([extensionZip(), Buffer.from('unparsed trailing bytes')]);
  assert.throws(() => validateNarutoExtensionArchive(trailing), /incomplete/);
  assert.throws(() => validateNarutoExtensionArchive(extensionZip(extensionFiles(), true, false, true)), /compression stream/);
  assert.throws(() => validateNarutoExtensionArchive(extensionZip({...extensionFiles(), 'portal.js': Buffer.from([0xff])})), /UTF-8/);
  const dishonestSize = extensionZip(extensionFiles(), true);
  const dishonestCentral = dishonestSize.readUInt32LE(dishonestSize.length - 6);
  dishonestSize.writeUInt32LE(1, dishonestCentral + 24); dishonestSize.writeUInt32LE(1, 22);
  assert.throws(() => validateNarutoExtensionArchive(dishonestSize), /compression stream/);
});
